import copy
def assess(proxies,expected_revision,now,max_age):
 if not isinstance(proxies,list) or not isinstance(expected_revision,str) or not expected_revision or type(now)is not int or type(max_age)is not int or max_age<0:raise ValueError('invalid input')
 seen=set();out=[]
 for item in proxies:
  if not isinstance(item,dict) or set(item)!={'id','revision','connected','observed_at','xds'}:raise ValueError('invalid record')
  ident=item['id'];revision=item['revision'];observed=item['observed_at'];xds=item['xds']
  if not isinstance(ident,str) or not ident or ident in seen or not isinstance(revision,str) or type(item['connected'])is not bool or type(observed)is not int or observed>now or not isinstance(xds,dict) or set(xds)-{'CDS','LDS','EDS','RDS'}:raise ValueError('invalid record')
  seen.add(ident);reasons=[]
  if not item['connected']:reasons.append('disconnected')
  if revision!=expected_revision:reasons.append('revision_mismatch')
  if now-observed>max_age:reasons.append('snapshot_expired')
  for key in ['CDS','LDS','EDS','RDS']:
   status=xds.get(key,'MISSING')
   if status not in {'SYNCED','STALE','NOT_SENT','UNKNOWN','MISSING'}:raise ValueError('invalid status')
   if status!='SYNCED':reasons.append(key+':'+status)
  out.append({'id':ident,'configuration_ready':not reasons,'reasons':reasons,'business_health':'not_tested'})
 return sorted(out,key=lambda row:row['id'])

